ions{display:flex;gap:8px;flex-shrink:0}body.fi-modal-open{overflow:hidden}.swal2-container{z-index:20000!important}@media(max-width:760px){.fi-summary{grid-template-columns:repeat(2,1fr)}.fi-modal{padding:6px}.fi-modal-dialog{width:99vw;max-height:97vh}.fi-modal-footer{align-items:flex-start;flex-direction:column}.fi-modal-actions{width:100%}.fi-modal-actions .btn{flex:1}}
