<script>
window.FREIGHT_INVOICE_CONFIG={projectId:<?php echo json_encode((int)($projectid??0));?>,companyId:<?php echo json_encode((int)($companyid??0));?>,subcompanyId:<?php echo json_encode((int)($subcompanyid??0));?>,initialClient:<?php echo json_encode(trim((string)($_GET['clientid']??'')));?>,initialTrip:<?php echo json_encode(trim((string)($_GET['trip_id']??'')));?>};
(function($){'use strict';const C=window.FREIGHT_INVOICE_CONFIG;let pending=[],generated=[],selectedClient='';const esc=v=>$('<div>').text(v==null?'':String(v)).html(),money=v=>(parseFloat(v)||0).toFixed(2);function today(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function load(){return $.post('ajax/module.php',{action:'list',projectid:C.projectId},null,'json').done(r=>{if(!r||!r.status){Swal.fire('Freight Invoice',r?.message||'Unable to load data.','error');return;}pending=r.data?.pending||[];generated=r.data?.generated||[];renderPending();renderGenerated();if(C.initialClient){$('#fi_client_filter').val(C.initialClient);filterRows();}if(C.initialTrip){$('.fi-trip-check').each(function(){const x=pending[parseInt($(this).data('i'),10)];if(x&&String(x.trip_id)===String(C.initialTrip))this.checked=true;});updateReview();C.initialTrip='';}}).fail(x=>Swal.fire('Freight Invoice',x.responseJSON?.message||'Unable to load data.','error'));}
function options(values,all){return '<option value="">'+all+'</option>'+[...new Set(values.map(v=>String(v||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b)).map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join('');}
function renderPending(){const clients={};pending.forEach(x=>clients[x.clientid]=x.clientname||x.clientid);$('#fi_client_filter').html('<option value="">All Clients</option>'+Object.keys(clients).sort((a,b)=>clients[a].localeCompare(clients[b])).map(k=>'<option value="'+esc(k)+'">'+esc(clients[k])+'</option>').join(''));$('#fi_vehicle_filter').html(options(pending.map(x=>x.vehicle_no),'All Vehicles'));$('#fi_driver_filter').html(options(pending.map(x=>x.driver_name),'All Drivers'));filterRows();}
function filterRows(){const q=String($('#fi_search').val()||'').toLowerCase(),cf=String($('#fi_client_filter').val()||''),vf=String($('#fi_vehicle_filter').val()||''),df=String($('#fi_driver_filter').val()||'');let h='';pending.forEach((x,i)=>{const txt=[x.clientname,x.clientid,x.trip_id,x.vehicle_no,x.driver_name,x.source_locationname,x.destination_locationname].join(' ').toLowerCase();if((cf&&String(x.clientid)!==cf)||(vf&&String(x.vehicle_no||'')!==vf)||(df&&String(x.driver_name||'')!==df)||(q&&!txt.includes(q)))return;h+='<tr data-i="'+i+'"><td class="text-center"><input type="checkbox" class="fi-trip-check" data-i="'+i+'"></td><td><b>'+esc(x.clientname||x.clientid)+'</b><br><small>'+esc(x.clientid)+'</small></td><td><b>'+esc(x.trip_id)+'</b></td><td>'+esc((x.trip_date||'').substring(0,10))+'</td><td><b>'+esc(x.vehicle_no||'-')+'</b><br><small>Driver: '+esc(x.driver_name||'-')+'</small><br><small>'+esc(x.source_locationname||'')+' → '+esc(x.destination_locationname||'')+'</small></td><td class="fi-money">'+money(x.original_freight)+'</td></tr>';});$('#fi_pending_rows').html(h||'<tr><td colspan="6" class="text-center text-muted">No pending recoverable freight for the selected filters.</td></tr>');updateReview();}
function selected(){return $('.fi-trip-check:checked').map(function(){return pending[parseInt($(this).data('i'),10)];}).get().filter(Boolean);}
function updateReview(){const rows=selected(),total=rows.reduce((s,x)=>s+(parseFloat(x.original_freight)||0),0);selectedClient=rows.length?String(rows[0].clientid):'';$('#fi_selected_count').text(rows.length+' trip(s) selected');$('#fi_selected_total').text(money(total));$('#fi_review_open').prop('disabled',!rows.length);if(!rows.length)closeReview();}
function openReview(){const rows=selected();if(!rows.length)return;selectedClient=String(rows[0].clientid);$('#fi_client').val(rows[0].clientname||selectedClient);$('#fi_date').val($('#fi_date').val()||today());$('#fi_warning').text('');$('#fi_date,#fi_reason').removeClass('fi-invalid');$('#fi_review_rows').html(rows.map(x=>'<tr data-trip="'+esc(x.trip_id)+'" data-original="'+money(x.original_freight)+'"><td><b>'+esc(x.trip_id)+'</b><br><small>'+esc(x.vehicle_no||'-')+' • '+esc(x.driver_name||'-')+'</small></td><td class="text-right fi-original">'+money(x.original_freight)+'</td><td><input type="number" class="form-control form-control-sm fi-disc-pct" min="0" max="100" step="0.01" value="0"></td><td><input type="number" class="form-control form-control-sm fi-disc-amt" min="0" step="0.01" value="0"></td><td><input type="number" class="form-control form-control-sm fi-adj" step="0.01" value="0"></td><td class="text-right fi-taxable">'+money(x.original_freight)+'</td></tr>').join(''));recalc();$('#fi_review_modal').addClass('open');$('body').addClass('fi-modal-open');setTimeout(()=>$('#fi_date').trigger('focus'),0);}
function closeReview(force){if(!force&&$('#fi_save').prop('disabled'))return;$('#fi_review_modal').removeClass('open');$('body').removeClass('fi-modal-open');}
function recalc(e){let o=0,d=0,a=0,t=0;$('#fi_review_rows tr').each(function(){const $r=$(this),orig=parseFloat($r.data('original'))||0;let pct=parseFloat($r.find('.fi-disc-pct').val())||0,disc=parseFloat($r.find('.fi-disc-amt').val())||0;if(e&&$(e.target).hasClass('fi-disc-pct')){pct=Math.max(0,Math.min(100,pct));disc=orig*pct/100;$r.find('.fi-disc-amt').val(money(disc));}else if(e&&$(e.target).hasClass('fi-disc-amt')){disc=Math.max(0,Math.min(orig,disc));pct=orig?disc/orig*100:0;$r.find('.fi-disc-pct').val(money(pct));$r.find('.fi-disc-amt').val(money(disc));}const adj=parseFloat($r.find('.fi-adj').val())||0,taxable=Math.max(0,orig-disc+adj);$r.find('.fi-taxable').text(money(taxable));o+=orig;d+=disc;a+=adj;t+=taxable;});const rates=(parseFloat($('#fi_cgst').val())||0)+(parseFloat($('#fi_sgst').val())||0)+(parseFloat($('#fi_igst').val())||0);$('#fi_t_original').text(money(o));$('#fi_t_discount').text(money(d));$('#fi_t_adjustment').text(money(a));$('#fi_t_taxable').text(money(t));$('#fi_t_invoice').text(money(t+t*rates/100));}
function payload(){return $('#fi_review_rows tr').map(function(){const $r=$(this);return {trip_id:String($r.data('trip')),discount_percent:parseFloat($r.find('.fi-disc-pct').val())||0,discount_amount:parseFloat($r.find('.fi-disc-amt').val())||0,adjustment:parseFloat($r.find('.fi-adj').val())||0};}).get();}
function renderGenerated(){const clients={};generated.forEach(x=>clients[x.clientid]=x.clientname||x.clientid);$('#fi_generated_client_filter').html('<option value="">All Clients</option>'+Object.keys(clients).sort((a,b)=>clients[a].localeCompare(clients[b])).map(k=>'<option value="'+esc(k)+'">'+esc(clients[k])+'</option>').join(''));$('#fi_generated_vehicle_filter').html(options(generated.flatMap(x=>String(x.vehicle_no||'').split(',').map(v=>v.trim())),'All Vehicles'));$('#fi_generated_driver_filter').html(options(generated.flatMap(x=>String(x.driver_name||'').split(',').map(v=>v.trim())),'All Drivers'));filterGeneratedRows();}
function filterGeneratedRows(){const q=String($('#fi_generated_search').val()||'').toLowerCase(),cf=String($('#fi_generated_client_filter').val()||''),vf=String($('#fi_generated_vehicle_filter').val()||''),df=String($('#fi_generated_driver_filter').val()||'');let h='';generated.forEach(x=>{const vehicles=String(x.vehicle_no||'').split(',').map(v=>v.trim()),drivers=String(x.driver_name||'').split(',').map(v=>v.trim()),txt=[x.invoice_no,x.clientname,x.clientid,x.trip_ids,x.vehicle_no,x.driver_name].join(' ').toLowerCase();if((cf&&String(x.clientid)!==cf)||(vf&&!vehicles.includes(vf))||(df&&!drivers.includes(df))||(q&&!txt.includes(q)))return;const base='prints/invoice.php?invoice_id='+encodeURIComponent(x.invoice_id);h+='<tr><td><b>'+esc(x.invoice_no)+'</b></td><td>'+esc(x.invoice_date||'')+'</td><td>'+esc(x.clientname||x.clientid)+'</td><td>'+esc(x.trip_ids||'')+'</td><td><b>'+esc(x.vehicle_no||'-')+'</b><br><small>Driver: '+esc(x.driver_name||'-')+'</small></td><td class="fi-money">'+money(x.invoice_amount)+'</td><td class="fi-generated"><a class="btn btn-sm btn-outline-primary" target="_blank" href="'+base+'&mode=inline">View</a><a class="btn btn-sm btn-outline-success" href="'+base+'&mode=download">Download</a></td></tr>';});$('#fi_generated_rows').html(h||'<tr><td colspan="7" class="text-center text-muted">No generated freight invoice for the selected filters.</td></tr>');}
$(document).on('change','.fi-trip-check',function(){const x=pending[parseInt($(this).data('i'),10)];if(this.checked){const already=selected().filter(y=>y!==x);if(already.some(y=>String(y.clientid)!==String(x.clientid))){this.checked=false;Swal.fire('One Client Only','Select trips belonging to the same client.','warning');}}updateReview();});$(document).on('input change','.fi-disc-pct,.fi-disc-amt,.fi-adj,#fi_cgst,#fi_sgst,#fi_igst',recalc);$('#fi_search').on('input',filterRows);$('#fi_client_filter,#fi_vehicle_filter,#fi_driver_filter').on('change',filterRows);$('#fi_generated_search').on('input',filterGeneratedRows);$('#fi_generated_client_filter,#fi_generated_vehicle_filter,#fi_generated_driver_filter').on('change',filterGeneratedRows);$('#fi_all').on('change',function(){const checks=$('.fi-trip-check:visible');if(!this.checked){checks.prop('checked',false);updateReview();return;}const first=checks.first();if(!first.length)return;const cid=pending[parseInt(first.data('i'),10)].clientid;checks.each(function(){this.checked=String(pending[parseInt($(this).data('i'),10)].clientid)===String(cid);});updateReview();});
$('#fi_save').on('click',function(){const rows=payload(),reason=$.trim($('#fi_reason').val()||'');$('#fi_warning').text('');if(!rows.length){$('#fi_warning').text('Select at least one trip.');return;}if(!$('#fi_date').val()){$('#fi_date').addClass('fi-invalid');$('#fi_warning').text('Invoice Date is required.');return;}$('#fi_date').removeClass('fi-invalid');if(rows.some(x=>x.discount_amount>0||Math.abs(x.adjustment)>0.00001)&&!reason){$('#fi_reason').addClass('fi-invalid');$('#fi_warning').text('Discount / Adjustment Reason is required.');return;}$('#fi_reason').removeClass('fi-invalid');Swal.fire({icon:'question',title:'Create Freight Invoice?',html:'Create one invoice for <b>'+rows.length+'</b> selected trip(s)?<br>Invoice total: <b>₹ '+esc($('#fi_t_invoice').text())+'</b>',showCancelButton:true,confirmButtonText:'Create Invoice'}).then(ans=>{if(!ans.isConfirmed)return;const $b=$('#fi_save').prop('disabled',true);$.post('ajax/module.php',{action:'save',projectid:C.projectId,companyid:C.companyId,subcompanyid:C.subcompanyId,clientid:selectedClient,invoice_date:$('#fi_date').val(),rows:JSON.stringify(rows),reason:reason,remarks:$('#fi_remarks').val(),cgst_percent:$('#fi_cgst').val(),sgst_percent:$('#fi_sgst').val(),igst_percent:$('#fi_igst').val()},null,'json').done(r=>{if(!r||!r.status){Swal.fire('Invoice Not Created',r?.message||'Unable to create invoice.','error');return;}closeReview(true);Swal.fire({icon:'success',title:'Freight Invoice Created',html:'Invoice: <b>'+esc(r.data.invoice_no)+'</b><br>Amount: <b>₹ '+money(r.data.invoice_amount)+'</b>',showCancelButton:true,confirmButtonText:'View Invoice',cancelButtonText:'Close'}).then(x=>{if(x.isConfirmed)window.open(r.data.print_url,'_blank');});load();}).fail(x=>Swal.fire('Invoice Not Created',x.responseJSON?.message||'Unable to create invoice.','error')).always(()=>$b.prop('disabled',false));});});
$('#fi_review_open').on('click',openReview);$('#fi_review_close,#fi_review_cancel').on('click',()=>closeReview());$('#fi_review_modal .fi-modal-backdrop').on('click',()=>closeReview());$(document).on('keydown',function(e){if(e.key==='Escape'&&$('#fi_review_modal').hasClass('open'))closeReview();});$('.fi-tabs button').on('click',function(){const tab=$(this).data('tab');closeReview();$('.fi-tabs button').removeClass('btn-primary').addClass('btn-outline-primary');$(this).addClass('btn-primary').removeClass('btn-outline-primary');$('#fi_pending_tab').toggle(tab==='pending');$('#fi_generated_tab').toggle(tab==='generated');});$('#fi_refresh').on('click',load);$(document).on('wheel','#fi_review_modal input[type=number]',function(e){e.preventDefault();this.blur();});$(load);
})(jQuery);
</script>
